INSERT INTO configuration (`key`, private, value)
VALUES ('generativeContentPrompt', 1, '{"placeExcerpt":"Please write an article about the place {name} ({country}) for my travel blog. The article will be published without editing, so it must be well-written, accurate, engaging, and factually rich. Focus on a general description of the place, highlighting its history, geographical setting, cultural and natural features, social and economic significance, and any unique characteristics that make it stand out. If it is a city or larger town, you may briefly mention population size or other essential facts, but avoid long descriptions of climate, transportation, or technical data. Do not list specific tourist attractions and do not use marketing phrases. The text should read smoothly and naturally, avoiding a dry encyclopedic tone, and instead capture what makes the place distinctive and worth knowing about. Keep it around 200 to 400 words depending on the significance of the place. Write it as a single paragraph without headings, emojis, or direct calls to action. The article should provide the reader with a valuable, factual, and comprehensive overview that sparks curiosity to learn more."}')